/* D124：团队需求确认单、变更与问题反馈；仅浏览器内存演示。 */
const blState={pid:'p1',actor:'morgan',preview:'正常',status:'整理中',version:1,converted:false,goal:false};
const blTitles=['账单列表分页','账单搜索筛选','账期汇总','税额展示','导出 CSV','导出字段排序','导出权限','导出失败重试','导出文件命名','操作审计','账单详情','接口文档','验收证据','上线移交'];
const blItems=blTitles.map((blTitle,blN)=>({phase:blN<4?'阶段一 · 基础账单':blN<10?'阶段二 · 导出能力':'阶段三 · 验收移交',title:blTitle,criteria:`当你使用${blTitle}时，系统应提供可按需求说明书核对的结果。`+(blN<7?' 当输入无效时，系统应提示原因且不泄露数据。':''),priority:blN<7?'高':'中',ref:'需求说明书 §'+(blN<4?'2':blN<10?'3':'4')+'.'+(blN+1),out:false}));
const blFeedback=[{id:'FB-31',title:'税额合计差 0.01 元',by:'Lee',source:'BIL#2 第 3 项 · 截图与账单.pdf',severity:'高',state:'待分诊',text:'行项目税额与发票合计不一致。'},{id:'FB-32',title:'同一账单税额偏差',by:'Zhao',source:'共享频道 · 截图',severity:'中',state:'待分诊',text:'与 FB-31 相同账期，请核对。'}];
function blEsc(blV){return String(blV??'').replace(/[&<>"']/g,blC=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[blC]));}
function blBtn(blT,blCall,blKind='',blReason=''){return `<span class="stack"><button class="btn ${blKind}" onclick="${blEsc(blCall)}" ${blReason?'disabled':''}>${blT}</button>${blReason?`<span class="muted xs">${blEsc(blReason)}</span>`:''}</span>`;}
function blKV(blRows){return `<dl class="kv">${blRows.map(blR=>`<dt>${blR[0]}</dt><dd>${blR[1]}</dd>`).join('')}</dl>`;}
function blTable(blHeaders,blRows){return `<div class="table-wrap"><table><thead><tr>${blHeaders.map(blH=>`<th>${blH}</th>`).join('')}</tr></thead><tbody>${blRows||`<tr><td colspan="${blHeaders.length}"><div class="empty">暂无记录</div></td></tr>`}</tbody></table></div>`;}
function blHuman(){return blState.actor==='morgan';}
function blEditable(){return blHuman()&&blState.status==='整理中'&&blState.preview==='正常';}
function blControls(){return `<div class="row wrap"><label>身份预览 <select onchange="blState.actor=this.value;route()"><option value="morgan" ${blHuman()?'selected':''}>你 · 人类对接人 Morgan</option><option value="iris" ${!blHuman()?'selected':''}>你 · 协调员 Agent Iris</option></select></label><span>状态预览</span>${['正常','异常','空'].map(blP=>`<button class="chip ${blState.preview===blP?'on':''}" onclick="blState.preview='${blP}';route()">${blP}</button>`).join('')}</div>${blState.preview==='异常'?'<div class="note warn">连接异常，写操作暂停；草稿保留。</div>':''}`;}
function blMissing(blPid){blState.pid=blPid||'p1';return blState.pid!=='p1'?head('项目','暂无需求确认单','当前项目还没有本页样例。')+card('项目',blKV([['编号',blEsc(blState.pid)]]))+card('需求项','<div class="empty">暂无已抽取需求项</div>')+card('签认状态','尚未发起签认'):'';}
PAGES.baseline=(blPid)=>{const blM=blMissing(blPid);if(blM)return blM;const blReason=!blHuman()?'仅人类对接人可执行':blState.preview!=='正常'?'当前预览暂停写操作':blState.status!=='整理中'?'已发出的版本冻结；已签认基线只能通过变更调整':'';return head('项目 · 账单中心','需求确认单','从 SOW / 清单抽取；签认前不转换为内部需求。')+blControls()+`<div class="stack">${card('来源与范围',blKV([['来源','账单中心二期需求说明书.docx · 甲方清单'],['整理','3 个阶段 · 初始抽取 14 条需求项 · 21 条验收标准'],['范围外','历史账单数据回填；第三方支付渠道对接'],['里程碑','M1 10-20 · M2 10-27 · M3 10-29 · M4 11-03 · M5 11-05']]))}${card('需求项',blTable(['阶段','需求项','验收标准','优先级','来源引用','操作'],blState.preview==='空'?'':blItems.map((blIt,blN)=>`<tr><td>${blEsc(blIt.phase)}</td><td>${blEsc(blIt.title)}${blIt.out?' <span class="badge b-stale">范围外</span>':''}</td><td>${blEsc(blIt.criteria)}</td><td>${blIt.priority}</td><td>${blEsc(blIt.ref)}</td><td><div class="row wrap">${['编辑','合并','拆分','标范围外'].map(blA=>blBtn(blA,`blEdit(${blN},'${blA}')`,blA==='标范围外'?'danger sm':'sm',blReason||(blA==='合并'&&blItems.length<2?'至少需要两条需求项':''))).join('')}</div></td></tr>`).join('')))}${card('版本与甲方签认',blKV([['确认单',`BL-7 v${blState.version}`],['状态',blState.status],['签认权限','Lee 可签认；Zhao 只读'],['签认回执',blState.status==='已签认'?'Lee · 2026-10-12 10:30（样例回执）':'尚未收到']])+`<div class="row wrap">${blBtn('发给甲方签认','blPublish()','primary',blReason||(!blItems.some(blIt=>!blIt.out)?'没有本期需求项':''))}${blBtn('预览已签认回执',"blState.status='已签认';route()",'ghost sm',!blHuman()?'仅团队人类可切换样例':blState.status!=='待甲方签认'?'先发出确认单':'')}</div><p class="muted small">发送前由你亲自核对范围、日期、价格与承诺；版本快照冻结，签认不能由 Agent 代替。</p>`)}${card('签认后的转换链路',blKV([['内部需求',blState.converted?'R-21 v1 · 来自 BL-7 v1':'待签认后转换'],['目标 / 关键结果',blState.goal?'人已确认':'Agent 草案 · 待人确认'],['后续链路','计划 → 任务 → 内部质量门 → 团队接受 → 交付']])+`<div class="row wrap">${blBtn('转为内部需求 R-21','blConvert()','primary',!blHuman()?'仅人类对接人可转换':blState.status!=='已签认'?'需甲方签认':blState.converted?'已转换':blState.preview!=='正常'?'写操作暂停':'')}${blBtn('确认目标与关键结果草案','blGoal()','',!blHuman()?'需人确认':!blState.converted?'先转换为内部需求':blState.goal?'已确认':blState.preview!=='正常'?'写操作暂停':'')}</div>${blState.converted?'<p>内部需求示例：<a href="#/requirement/R-12">R-12</a></p>':''}${blState.goal?'<p>在<a href="#/work/p1">项目任务</a>中安排计划与任务。</p>':''}<div class="note info">甲方只看到里程碑与交付；内部返工、验收记录不穿透到甲方。</div>`)}</div>`;};
function blEdit(blN,blAction){if(!blEditable())return toast('当前版本不可编辑');const blIt=blItems[blN];openDrawer(`<div class="stack" style="padding:24px"><h3>${blAction}需求项</h3><p>${blEsc(blIt.title)} · ${blEsc(blIt.ref)}</p>${blAction==='标范围外'?'<div class="note danger">从本期范围移出，影响后续签认；需重新认证。</div><label><input id="bl-auth" type="checkbox">你已重新认证（原型模拟）</label>':blAction==='合并'?`<label>目标需求<select id="bl-target">${blItems.map((blI,blJ)=>blJ===blN?'':`<option value="${blJ}">${blEsc(blI.title)}</option>`).join('')}</select></label>`:`<label class="stack">需求项<input id="bl-title" maxlength="200" value="${blAction==='拆分'?'':blEsc(blIt.title)}"></label><label class="stack">验收标准<textarea id="bl-criteria" maxlength="1000">${blAction==='拆分'?'':blEsc(blIt.criteria)}</textarea></label><label>优先级<select id="bl-priority"><option ${blIt.priority==='高'?'selected':''}>高</option><option ${blIt.priority==='中'?'selected':''}>中</option><option>低</option></select></label>`}<div class="row">${blBtn('保存',`blSave(${blN},'${blAction}')`,blAction==='标范围外'?'danger':'primary')}${blBtn('关闭','closeDrawer()','ghost')}</div></div>`);}
function blSave(blN,blAction){if(!blEditable())return toast('版本或权限已变化');const blIt=blItems[blN];if(blAction==='标范围外'){if(!document.getElementById('bl-auth').checked)return toast('需重新认证');blIt.out=true;}else if(blAction==='合并'){const blTarget=blItems[Number(document.getElementById('bl-target').value)];blTarget.title+=' / '+blIt.title;blTarget.criteria+=' '+blIt.criteria;blTarget.ref+='；'+blIt.ref;blItems.splice(blN,1);}else{const blTitle=document.getElementById('bl-title').value.trim(),blCriteria=document.getElementById('bl-criteria').value.trim();if(!blTitle||!blCriteria)return toast('请填写需求项与验收标准');const blNew={...blIt,title:blTitle,criteria:blCriteria,priority:document.getElementById('bl-priority').value};if(blAction==='拆分')blItems.splice(blN+1,0,blNew);else blItems[blN]=blNew;}closeDrawer();route();}
function blPublish(){if(!blEditable()||!blItems.some(blIt=>!blIt.out))return toast('当前不能发送');openModal(`<div class="stack" style="padding:24px"><h3>发给甲方签认</h3><div class="note warn">请亲自核对范围、日期、价格与承诺；发送后冻结 BL-7 v${blState.version}。</div><label><input id="bl-confirm" type="checkbox">你已核对确认单及承诺</label>${blBtn('发送','blSend()','primary')}${blBtn('取消','closeModal()','ghost')}</div>`);}
function blSend(){if(!blEditable()||!document.getElementById('bl-confirm').checked)return toast('请由对接人核对确认单');blState.snapshot=JSON.parse(JSON.stringify(blItems));blState.status='待甲方签认';closeModal();route();toast('已发给 Lee 签认（本地演示）');}
function blConvert(){if(!blHuman()||blState.preview!=='正常'||blState.status!=='已签认'||blState.converted)return;blState.converted=true;route();toast('已转换为内部需求 R-21（样例）');}
function blGoal(){if(!blHuman()||blState.preview!=='正常'||!blState.converted||blState.goal)return;blState.goal=true;route();}
PAGES.changes=(blPid)=>head('项目','变更','按同版影响评估取得甲方确认，容差内告知结果。')+card('项目与基线',blKV([['项目',blEsc(blPid||'p1')],['基线',`R-12 v${cgOriginal.version}`],['负责人','Morgan · 人类']]))+card('变更列表',blTable(['编号','变更内容','状态','工期影响','甲方确认'],(blPid&&blPid!=='p1')?'':Object.values(cgChanges).map(blC=>`<tr><td><a href="#/change/${blC.id}">${blC.id}</a></td><td>${blEsc(blC.title)}</td><td>${cgBadge(blC)}</td><td>+${blC.days??'待评估'} 天 · ${blC.expected}</td><td>${cgApprovalText(blC)}</td></tr>`).join('')))+card('处理规则',blKV([['越界','时间 / 成本 / 范围越界须甲方确认'],['冻结','待确认时不得修改影响评估'],['提醒','7 天提醒甲方；14 天提醒团队；不自动决定']]));
PAGES.feedback=(blPid)=>{blState.pid=blPid||'p1';return head('项目','问题反馈','甲方问题由团队分诊，内部缺陷与返工不直接对甲方展示。')+blControls()+card('反馈概况',blKV([['项目',blEsc(blState.pid)],['待分诊',blFeedback.filter(blF=>blF.state==='待分诊').length],['负责人','Morgan · Iris 协助起草分诊']]))+card('分诊列表',blTable(['编号 / 来源','甲方原话','严重程度','状态','操作'],blState.preview==='空'||blState.pid!=='p1'?'':blFeedback.map((blF,blN)=>`<tr><td>${blF.id} · ${blF.by}<p>${blEsc(blF.source)}</p></td><td>${blEsc(blF.title)}<p>${blEsc(blF.text)}</p></td><td>${blF.severity}</td><td>${blEsc(blF.state)}${blF.defect?'<p><a href="#/defect/BUG-311">BUG-311</a></p>':''}${blF.message?`<p>给甲方的话：${blEsc(blF.message)}</p>`:''}</td><td>${['转为缺陷','合并','不处理（需给甲方的话）'].map(blA=>blBtn(blA,`blTriage(${blN},'${blA}')`,blA.startsWith('不处理')?'danger sm':'sm',!blHuman()?'仅人类分诊负责人可确认':blState.preview!=='正常'?'写操作暂停':blF.state!=='待分诊'?'已处理，不可重复操作':'')).join('')}</td></tr>`).join('')))+card('分诊规则',blKV([['转为缺陷','保留甲方原话、来源与证据，关联内部缺陷 BUG-311'],['合并','目标不得为自身或已结束反馈；理由必填'],['不处理','给甲方的话必填；保留反馈历史']]));};
function blTriage(blN,blAction){if(!blHuman()||blState.preview!=='正常'||blFeedback[blN].state!=='待分诊')return;const blTargets=blFeedback.map((blF,blJ)=>blJ!==blN&&blF.state==='待分诊'?`<option value="${blJ}">${blF.id} · ${blEsc(blF.title)}</option>`:'').join('');if(blAction==='合并'&&!blTargets)return toast('没有可合并的未结束反馈');openDrawer(`<form class="stack" style="padding:24px" onsubmit="blResolve(event,${blN},'${blAction}')"><h3>${blAction}</h3><p>${blEsc(blFeedback[blN].title)}</p>${blAction==='合并'?`<label>合并目标<select name="target">${blTargets}</select></label><label class="stack">合并理由<textarea name="reason" required maxlength="2000"></textarea></label>`:''}<label class="stack">给甲方的话<textarea name="message" required maxlength="2000"></textarea></label>${blAction.startsWith('不处理')?'<div class="note danger">结束本次反馈处理并告知甲方理由；保留原文，需重新认证。</div><label><input name="auth" type="checkbox" required>你已重新认证（模拟）</label>':''}<button class="btn ${blAction.startsWith('不处理')?'danger':'primary'}">确认</button>${blBtn('关闭','closeDrawer()','ghost')}</form>`);}
function blResolve(blE,blN,blAction){blE.preventDefault();if(!blHuman()||blState.preview!=='正常'||blFeedback[blN].state!=='待分诊')return;const blForm=blE.target,blMessage=blForm.elements.message.value.trim();if(!blMessage)return toast('请填写给甲方的话');const blF=blFeedback[blN];if(blAction==='合并'){const blTarget=blFeedback[Number(blForm.elements.target.value)],blReason=blForm.elements.reason.value.trim();if(!blReason||!blTarget||blTarget===blF||blTarget.state!=='待分诊')return toast('目标或理由无效');blF.state='已合并至 '+blTarget.id;blF.reason=blReason;}else if(blAction==='转为缺陷'){blF.state='已转为缺陷';blF.defect='BUG-311';}else{if(!blForm.elements.auth.checked)return toast('需重新认证');blF.state='不处理';}blF.message=blMessage;closeDrawer();route();}
TITLES.baseline='需求确认单';TITLES.changes='变更';TITLES.feedback='问题反馈';
NAVPARENT.baseline='project';NAVPARENT.changes='project';NAVPARENT.feedback='project';
